// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import java.util.Map;

import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierFallbackReason;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsAvailability;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsHeapGovernor;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsMemoryPurpose;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsStatus;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsTier;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierSynopsisStatus;
import org.eclipse.rdf4j.sail.lmdb.frontier.LmdbStatisticsService;

/**
 * Renders the complete Frontier availability picture as human-readable log text.
 *
 * <p>
 * Planning silently chooses between two mutually exclusive evidence lanes. When Frontier Statistics V2 is open and
 * {@code READY}, {@code LmdbPackedCostModel} costs through the mapped statistics lane. Otherwise it falls back to the
 * legacy {@code LmdbFrontierSynopsisService} arena lane, whose status is then what plans report. Without this report
 * the decline is invisible: the V2 open gate skips silently, and a rejected legacy manifest surfaces only as an opaque
 * {@code plannedFrontierStatus} on a query plan.
 * </p>
 *
 * <p>
 * Every method here is read-only and allocation-light; nothing in this class influences planning or storage.
 * </p>
 */
final class LmdbFrontierDiagnostics {

	/** Minimum synopsis disk budget before the store opens Frontier Statistics V2. */
	static final long MINIMUM_STATISTICS_DISK_BUDGET_BYTES = 16L * 1024L * 1024L;

	/** Minimum governed heap budget before the store opens Frontier Statistics V2. */
	static final long MINIMUM_STATISTICS_HEAP_BUDGET_BYTES = 1024L;

	private static final String INDENT = "  ";

	private LmdbFrontierDiagnostics() {
	}

	/**
	 * Returns why the mapped Frontier Statistics V2 lane cannot be used, or {@code null} when it can.
	 *
	 * <p>
	 * The returned text names the exact failed gate so a declining planner is never ambiguous.
	 * </p>
	 *
	 * @param mode       configured estimator mode
	 * @param statistics the store-owned V2 service, or {@code null} when it never opened
	 * @return a short decline reason, or {@code null} when the mapped lane is usable
	 */
	static String mappedLaneDeclineReason(FrontierEstimatorMode mode, LmdbStatisticsService statistics) {
		if (mode != FrontierEstimatorMode.AUTHORITATIVE) {
			return "frontier estimator mode is " + mode + ", not authoritative";
		}
		if (statistics == null) {
			return "Frontier Statistics V2 never opened for this store";
		}
		FrontierStatisticsStatus status = statistics.status();
		if (status.availability() != FrontierStatisticsAvailability.READY) {
			return "Frontier Statistics V2 availability is " + status.availability()
					+ " (build phase " + status.buildPhase() + ", fallback " + status.fallbackReason() + ")";
		}
		if (status.fallbackReason() != FrontierFallbackReason.NONE) {
			return "Frontier Statistics V2 is READY but reports fallback reason " + status.fallbackReason();
		}
		return null;
	}

	/**
	 * Renders the complete Frontier report: configuration, the V2 open gate, governed heap, generation state, disk use,
	 * the legacy synopsis status, and the resulting planner lane.
	 *
	 * @param context     short description of what triggered the report, such as {@code "store startup"}
	 * @param config      the store configuration in effect
	 * @param statistics  the store-owned V2 service, or {@code null} when it never opened
	 * @param governor    the governed heap accountant, or {@code null} when V2 never opened
	 * @param openFailure the exception message that prevented V2 from opening, or {@code null}
	 * @param legacy      the legacy synopsis status, or {@code null} when that service is absent
	 * @return a multi-line report
	 */
	static String report(String context, LmdbStoreConfig config, LmdbStatisticsService statistics,
			FrontierStatisticsHeapGovernor governor, String openFailure, FrontierSynopsisStatus legacy) {
		StringBuilder text = new StringBuilder(2048);
		text.append("Frontier diagnostics (").append(context).append(')');
		appendConfiguration(text, config);
		appendOpenGate(text, config, statistics, openFailure);
		appendHeap(text, governor);
		appendStatistics(text, statistics);
		appendLegacy(text, legacy);
		appendLane(text, config, statistics, legacy);
		return text.toString();
	}

	private static void appendConfiguration(StringBuilder text, LmdbStoreConfig config) {
		section(text, "configuration");
		field(text, "estimatorMode", config.getFrontierEstimatorMode());
		field(text, "synopsisBudget (steady disk cap)", bytes(config.getFrontierSynopsisBudgetBytes()));
		field(text, "heapBudget (effective)", bytes(config.getFrontierHeapBudgetBytes()));
		field(text, "heapBudget (default when unset)", bytes(LmdbStoreConfig.FRONTIER_HEAP_BUDGET_BYTES));
		field(text, "queryMemoryBudget (deprecated)", bytes(config.getFrontierQueryMemoryBudgetBytes()));
		field(text, "queryIndexBudget (deprecated, effective)",
				bytes(config.getEffectiveFrontierQueryIndexBudgetBytes()));
		field(text, "initialMaterializationWorkUnits (deprecated)",
				config.getFrontierInitialMaterializationWorkUnits());
		field(text, "designLanes", config.getFrontierDesignLanes());
		field(text, "auditLanes", config.getFrontierAuditLanes());
		field(text, "statisticsMaxLagMillis", config.getFrontierStatisticsMaxLagMillis());
		field(text, "deleteReserveFraction", config.getFrontierDeleteReserveFraction());
		field(text, "cacheEvidenceBudget", bytes(config.getFrontierCacheEvidenceBudgetBytes()));
		/*
		 * getFrontierHeapBudgetBytes() aliases the deprecated query-memory budget when that value was set explicitly
		 * and the heap budget was not. A per-query arena value silently becomes the whole V2 governor and can starve
		 * the builder, so name the collision rather than leaving two equal numbers for a reader to correlate.
		 */
		if (config.getFrontierHeapBudgetBytes() == config.getFrontierQueryMemoryBudgetBytes()
				&& config.getFrontierHeapBudgetBytes() != LmdbStoreConfig.FRONTIER_HEAP_BUDGET_BYTES) {
			field(text, "WARNING", "heapBudget equals the deprecated queryMemoryBudget; the deprecated setting is"
					+ " governing all Frontier Statistics V2 heap. Set frontierHeapBudgetBytes explicitly.");
		}
	}

	private static void appendOpenGate(StringBuilder text, LmdbStoreConfig config, LmdbStatisticsService statistics,
			String openFailure) {
		section(text, "statistics V2 open gate");
		boolean enabled = config.getFrontierEstimatorMode() != FrontierEstimatorMode.OFF;
		long disk = config.getFrontierSynopsisBudgetBytes();
		long heap = config.getFrontierHeapBudgetBytes();
		gate(text, "estimatorMode != OFF", enabled, String.valueOf(config.getFrontierEstimatorMode()));
		gate(text, "synopsisBudget >= " + bytes(MINIMUM_STATISTICS_DISK_BUDGET_BYTES),
				disk >= MINIMUM_STATISTICS_DISK_BUDGET_BYTES, bytes(disk));
		gate(text, "heapBudget >= " + bytes(MINIMUM_STATISTICS_HEAP_BUDGET_BYTES),
				heap >= MINIMUM_STATISTICS_HEAP_BUDGET_BYTES, bytes(heap));
		field(text, "opened", statistics != null);
		if (openFailure != null && !openFailure.isBlank()) {
			field(text, "openFailure", openFailure);
		}
	}

	private static void appendHeap(StringBuilder text, FrontierStatisticsHeapGovernor governor) {
		section(text, "governed heap");
		if (governor == null) {
			field(text, "governor", "absent (Frontier Statistics V2 never opened)");
			return;
		}
		field(text, "budget", bytes(governor.budgetBytes()));
		field(text, "safetyMargin", bytes(governor.safetyMarginBytes()));
		field(text, "queryReserve", bytes(governor.queryReserveBytes()));
		field(text, "maximumQuery", bytes(governor.maximumQueryBytes()));
		field(text, "maximumNonQuery", bytes(governor.maximumNonQueryBytes()));
		field(text, "reservedTotal", bytes(governor.reservedBytes()));
		for (FrontierStatisticsMemoryPurpose purpose : FrontierStatisticsMemoryPurpose.values()) {
			field(text, "reserved[" + purpose + ']', bytes(governor.reservedBytes(purpose)));
		}
	}

	private static void appendStatistics(StringBuilder text, LmdbStatisticsService statistics) {
		section(text, "statistics V2 generation");
		if (statistics == null) {
			field(text, "status", "absent (never opened)");
			return;
		}
		FrontierStatisticsStatus status = statistics.status();
		field(text, "availability", status.availability());
		field(text, "fallbackReason", status.fallbackReason());
		field(text, "buildPhase", status.buildPhase());
		field(text, "generationId", status.generationId());
		field(text, "baseEpoch", status.baseEpoch());
		field(text, "coveredEpoch", status.coveredEpoch());
		field(text, "coveredSequence", status.coveredSequence());
		field(text, "lagMillis", status.lagMillis());
		field(text, "scanRate", status.scanRate());
		field(text, "buildEtaMillis", status.buildEtaMillis());
		field(text, "deleteDebt", status.deleteDebt());
		field(text, "auditLeafQError", status.auditLeafQError());
		field(text, "auditJoinQError", status.auditJoinQError());
		field(text, "lastFailure", status.lastFailure().isEmpty() ? "(none)" : status.lastFailure());
		appendTierBytes(text, status.diskBytesByTier());
		appendPurposeBytes(text, status.heapBytesByPurpose());
	}

	private static void appendTierBytes(StringBuilder text, Map<FrontierStatisticsTier, Long> diskBytesByTier) {
		long total = 0L;
		for (FrontierStatisticsTier tier : FrontierStatisticsTier.values()) {
			long value = diskBytesByTier.getOrDefault(tier, 0L);
			total += value;
			field(text, "disk[" + tier + ']', bytes(value));
		}
		field(text, "disk[TOTAL]", bytes(total));
	}

	private static void appendPurposeBytes(StringBuilder text,
			Map<FrontierStatisticsMemoryPurpose, Long> heapBytesByPurpose) {
		long total = 0L;
		for (FrontierStatisticsMemoryPurpose purpose : FrontierStatisticsMemoryPurpose.values()) {
			long value = heapBytesByPurpose.getOrDefault(purpose, 0L);
			total += value;
			field(text, "heap[" + purpose + ']', bytes(value));
		}
		field(text, "heap[TOTAL]", bytes(total));
	}

	private static void appendLegacy(StringBuilder text, FrontierSynopsisStatus legacy) {
		section(text, "legacy synopsis (fallback lane)");
		if (legacy == null) {
			field(text, "status", "absent");
			return;
		}
		field(text, "status", legacy);
		/*
		 * These statuses are terminal: LmdbSailStore.frontierSynopsisNeedsRebuild only schedules a rebuild for
		 * DIRTY_INSERTION, DIRTY_DELETION, and BUDGET_EXCEEDED, so an incompatible or damaged generation stays broken
		 * for the process lifetime. Say so, because a fallback that can never recover looks like a transient state.
		 */
		switch (legacy) {
		case HASH_MISMATCH, SCHEMA_MISMATCH, VERSION_MISMATCH -> field(text, "note",
				"the stored generation was built by an incompatible Frontier version; it is never rebuilt"
						+ " automatically, so this lane stays unavailable until the frontier-synopsis directory is"
						+ " removed or rebuilt");
		case STORE_MISMATCH, EPOCH_MISMATCH, MISSING, CORRUPT, TRUNCATED -> field(text, "note",
				"this lane is terminal and is never rebuilt automatically");
		default -> {
			// READY, DISABLED_*, DIRTY_*, and BUDGET_EXCEEDED need no additional explanation.
		}
		}
	}

	private static void appendLane(StringBuilder text, LmdbStoreConfig config, LmdbStatisticsService statistics,
			FrontierSynopsisStatus legacy) {
		section(text, "selected planner lane");
		String decline = mappedLaneDeclineReason(config.getFrontierEstimatorMode(), statistics);
		if (decline == null) {
			field(text, "lane", "frontier-statistics-v2 (mapped statistics)");
			return;
		}
		field(text, "lane", "legacy frontier-synopsis arena");
		field(text, "declined", decline);
		field(text, "consequence", "query plans report the legacy status"
				+ (legacy == null ? "" : " (" + legacy + ')') + " rather than mapped V2 evidence");
	}

	private static void section(StringBuilder text, String name) {
		text.append(System.lineSeparator()).append(INDENT).append('[').append(name).append(']');
	}

	private static void gate(StringBuilder text, String name, boolean satisfied, String observed) {
		field(text, name, (satisfied ? "pass" : "FAIL") + " (observed " + observed + ')');
	}

	private static void field(StringBuilder text, String name, Object value) {
		text.append(System.lineSeparator()).append(INDENT).append(INDENT).append(name).append(": ").append(value);
	}

	private static String bytes(long value) {
		if (value < 1024L) {
			return value + " B";
		}
		String[] units = { "KiB", "MiB", "GiB", "TiB" };
		double scaled = value;
		int unit = -1;
		while (scaled >= 1024.0d && unit < units.length - 1) {
			scaled /= 1024.0d;
			unit++;
		}
		return String.format("%.1f %s (%d B)", scaled, units[unit], value);
	}
}
